import {createBirthdayScene} from './scene.js';
import {DURATION} from './choreography.js';
const $=s=>document.querySelector(s);
let movie=null,elapsed=0,playing=false,finished=false,frameId=0,startAt=0,startTime=0,stopAt=DURATION,actionMode=false;
const chapters=t=>t<5?['A LITTLE ENTRANCE','A little magic, on your special day.']:t<8.8?['MAKE A WISH','Close your eyes, Nadia. Make a wish.']:t<11.5?['CANDLES & WISHES','May every little wish come true.']:t<16?['TIME FOR CAKE','A little sweetness for a beautiful new year.']:t<21.4?['YOUR BIRTHDAY SLICE','Make room for something sweet.']:t<25.6?['SERVED WITH LOVE','The first slice is yours.']:['HAPPY BIRTHDAY','Happy Birthday, Nadia Noor! ♡'];

function updateHeading(){
 const title=elapsed<5?'A little magic awaits':elapsed<8.8?'Make a wish, Nadia':elapsed<11.5?'Blow out the candles':elapsed<16?'Time for something sweet':elapsed<21.4?'Let’s cut the cake':elapsed<25.6?'The first slice is yours':'Happy Birthday, Nadia!';
 const heading=$('.title h1');if(heading.textContent!==title){heading.textContent=title;$('.title p').textContent=elapsed>=25.6?'WITH LOVE, FOR NADIA NOOR':'NADIA NOOR / YOUR BIRTHDAY STORY';$('.title > span').textContent=chapters(elapsed)[1];if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heading.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:350,easing:'ease-out'});}
}

function sync(){updateHeading();if(movie){$('#blow').disabled=playing||elapsed>=11.5;$('#cut').disabled=playing||elapsed<11.5||elapsed>=25.6;$('#celebrate').disabled=playing||elapsed<25.6;$('#action-status').textContent=playing?'Enjoy the moment - you can still rotate the scene.':elapsed<11.5?'Tap the candles or choose Blow candles.':elapsed<25.6?'Tap the cake or choose Cut the cake.':'Your slice is ready. Open your birthday wish!';}const c=chapters(elapsed);$('#seek').value=elapsed;$('#seek').style.setProperty('--progress',`${elapsed/DURATION*100}%`);$('#time').textContent=`00:${String(Math.floor(elapsed)).padStart(2,'0')} / 00:${DURATION}`;$('#chapter').textContent=c[0];$('#caption').textContent=elapsed>0?c[1]:'';$('#pause').textContent=playing?'Ⅱ':'▶';$('#pause').setAttribute('aria-label',playing?'Pause story':'Resume story');$('#seek').disabled=!movie;}
function paint(){if(!movie)return;movie.render(elapsed);$('.title').style.opacity=1;sync();}
function pause(){playing=false;cancelAnimationFrame(frameId);sync();}
function tick(now){if(!playing)return;elapsed=Math.min(stopAt,startTime+(now-startAt)/1000);paint();if(elapsed>=stopAt){playing=false;finished=elapsed>=DURATION;sync();if(finished&&!$('#wish').open)$('#wish').showModal();return;}frameId=requestAnimationFrame(tick);}
function resume(){if(!movie)return;playing=true;startAt=performance.now();startTime=elapsed;sync();frameId=requestAnimationFrame(tick);}
function replay(){if(!movie)return;stopAt=DURATION;actionMode=false;movie.resetCamera();pause();$('#wish').close();elapsed=0;finished=false;$('#start').hidden=true;$('#pause').disabled=false;$('#replay').disabled=false;paint();resume();}
$('#begin').onclick=replay;$('#replay').onclick=replay;$('#again').onclick=replay;$('#close').onclick=()=>$('#wish').close();$('#pause').onclick=()=>{if(finished)replay();else if(playing)pause();else {stopAt=DURATION;resume();}};$('#seek').oninput=()=>{if(!movie)return;stopAt=DURATION;const requested=Number($('#seek').value);pause();elapsed=requested;finished=elapsed>=DURATION;$('#start').hidden=true;$('#pause').disabled=false;$('#replay').disabled=false;$('#wish').close();paint();if(finished)$('#wish').showModal();};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)pause();});

function birthdayAction(kind){if(!movie||playing)return;const ranges={blow:[7.7,11.5],cut:[11.5,25.6],celebrate:[25.6,30]};if(kind==='cut'&&elapsed<11.5)return;if(kind==='blow'&&elapsed>=11.5)return;if(kind==='celebrate'&&elapsed<25.6)return;pause();actionMode=true;[elapsed,stopAt]=ranges[kind];finished=false;$('#start').hidden=true;$('#pause').disabled=false;$('#replay').disabled=false;paint();resume();}
$('#blow').onclick=()=>birthdayAction('blow');$('#cut').onclick=()=>birthdayAction('cut');$('#celebrate').onclick=()=>birthdayAction('celebrate');
$('#zoom-in').onclick=()=>movie?.moveCamera(0,0,.85);$('#zoom-out').onclick=()=>movie?.moveCamera(0,0,1.18);$('#reset-view').onclick=()=>movie?.resetCamera();
const canvas=$('#scene'),pointers=new Map();let dragDistance=0,pinchDistance=0;
canvas.addEventListener('pointerdown',e=>{if(!movie)return;canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});dragDistance=0;pinchDistance=0;canvas.classList.add('dragging');});
canvas.addEventListener('pointermove',e=>{const p=pointers.get(e.pointerId);if(!p||!movie)return;const dx=e.clientX-p.x,dy=e.clientY-p.y;dragDistance+=Math.abs(dx)+Math.abs(dy);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance>0&&d>0)movie.moveCamera(0,0,pinchDistance/d);pinchDistance=d;dragDistance=100;}else movie.moveCamera(dx,dy);});
function releasePointer(e){if(!pointers.has(e.pointerId))return;const tapped=dragDistance<7&&pointers.size===1&&e.type==='pointerup';pointers.delete(e.pointerId);pinchDistance=0;if(!pointers.size)canvas.classList.remove('dragging');if(tapped){const hit=movie.pick(e.clientX,e.clientY);if(hit==='candles')birthdayAction('blow');else if(hit==='cake')birthdayAction(elapsed<11.5?'blow':'cut');}}
canvas.addEventListener('pointerup',releasePointer);canvas.addEventListener('pointercancel',releasePointer);
canvas.addEventListener('wheel',e=>{e.preventDefault();movie?.moveCamera(0,0,Math.exp(Math.max(-150,Math.min(150,e.deltaY))*.0015));},{passive:false});
canvas.addEventListener('keydown',e=>{const moves={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12],'+':[0,0,.9],'=':[0,0,.9],'-':[0,0,1.1]};if(moves[e.key]){e.preventDefault();movie?.moveCamera(...moves[e.key]);}});

let ac,music=false,musicTimer,nextNote=0,noteIndex=0;const notes=[[67,.35],[67,.15],[69,.5],[67,.5],[72,.5],[71,1],[67,.35],[67,.15],[69,.5],[67,.5],[74,.5],[72,1],[67,.35],[67,.15],[79,.5],[76,.5],[72,.5],[71,.5],[69,1],[77,.35],[77,.15],[76,.5],[72,.5],[74,.5],[72,1.5]];
function musicLoop(){if(!music)return;while(nextNote<ac.currentTime+.3){const[n,d]=notes[noteIndex];const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=440*2**((n-69)/12);g.gain.setValueAtTime(.001,nextNote);g.gain.linearRampToValueAtTime(.065,nextNote+.012);g.gain.exponentialRampToValueAtTime(.001,nextNote+d);o.connect(g);g.connect(ac.destination);o.start(nextNote);o.stop(nextNote+d);nextNote+=d;noteIndex=(noteIndex+1)%notes.length;}musicTimer=setTimeout(musicLoop,100);}
$('#sound').onclick=async()=>{try{ac??=new(window.AudioContext||window.webkitAudioContext)();music=!music;if(music){await ac.resume();nextNote=ac.currentTime+.05;noteIndex=0;musicLoop();}else{clearTimeout(musicTimer);await ac.suspend();}$('#sound span').textContent=music?'Music on':'Music off';$('#sound').setAttribute('aria-pressed',String(music));$('#sound').setAttribute('aria-label',music?'Turn music off':'Turn music on');}catch{$('#sound span').textContent='Music unavailable';}};
export function inspectBirthdayFrame(){return {...movie?.inspect(),elapsed,playing,finished,wishOpen:$('#wish').open};}
try{movie=createBirthdayScene($('#scene'));elapsed=6.5;movie.resize(elapsed);paint();$('#caption').textContent='Your birthday, in every dimension.';new ResizeObserver(()=>{movie.resize(elapsed);}).observe($('#scene'));$('#loading').hidden=true;$('#begin').disabled=false;sync();}catch(e){$('#loading').hidden=true;$('#error').hidden=false;$('#start').hidden=true;console.error('Birthday scene unavailable',e);}
